package vn.hust.restaurant.service;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.Employee;import vn.hust.restaurant.repository.EmployeeRepository;public class EmployeeService{private final EmployeeRepository r;public EmployeeService(EmployeeRepository r){this.r=r;}public List<Employee>list(String k)throws SQLException{return r.findAll(k);}public int save(Employee x)throws SQLException{if(x.fullName().isBlank()||x.role().isBlank())throw new IllegalArgumentException("Tên và vai trò bắt buộc");return r.save(x);}public void account(int id,String user,String pass)throws SQLException{r.createOrResetAccount(id,user,SecurityUtil.hash(pass));}public void lock(int id,boolean x)throws SQLException{r.lockAccount(id,x);}}
